class BuildingTransactionDialog extends ConsumerStatefulWidget {
  const BuildingTransactionDialog({
    super.key,
    required this.onCancel,
    required this.coin,
  });

  final VoidCallback onCancel;
  final CryptoCurrency coin;

  @override
  ConsumerState<BuildingTransactionDialog> createState() =>
      _BuildingTransactionDialogState();
}

class _BuildingTransactionDialogState
    extends ConsumerState<BuildingTransactionDialog> {
  late final VoidCallback onCancel;

  @override
  void initState() {
    onCancel = widget.onCancel;

    super.initState();
  }

  @override
  Widget build(BuildContext context) {
    if (Util.isDesktop) {
      return Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const TxSendAnimation(width: 420),
          const SizedBox(height: 24),
          Text(l10n.sendGeneratingTransaction, style: STextStyles.desktopH3(context)),
          const SizedBox(height: 24),
          const RotatingArrows(width: 40, height: 40),
          const SizedBox(height: 32),
          SecondaryButton(
            buttonHeight: ButtonHeight.l,
            label: l10n.commonCancel,
            onPressed: () {
              onCancel.call();
            },
          ),
        ],
      );
    } else {
      return WillPopScope(
        onWillPop: () async {
          return false;
        },
        child: StackDialog(
          header: const TxSendAnimation(),
          title: l10n.sendGeneratingTransaction,
          icon: const RotatingArrows(width: 24, height: 24),
          rightButton: TextButton(
            style: Theme.of(context)
                .extension<StackColors>()!
                .getSecondaryEnabledButtonStyle(context),
            child: Text(l10n.commonCancel, style: STextStyles.itemSubtitle12(context)),
            onPressed: () {
              Navigator.of(context).pop();
              onCancel.call();
            },
          ),
        ),
      );
    }
  }
}

/// Build a transaction behind the "Generating transaction" dialog, like
/// the send screen. Returns null when the user cancels, or when building
/// fails (shown in a "Transaction failed" dialog).
Future<T?> showBuildingTransaction<T>({
  required BuildContext context,
  required CryptoCurrency coin,
  required Future<T> Function() build,
}) async {
  var cancelled = false;
  final navigator = Navigator.of(context, rootNavigator: true);
  unawaited(
    showDialog<void>(
      context: context,
      useSafeArea: false,
      barrierDismissible: false,
      builder: (context) {
        if (!Util.isDesktop) {
          // Its Cancel button closes it.
          return BuildingTransactionDialog(
            coin: coin,
            onCancel: () => cancelled = true,
          );
        }
        return DesktopDialog(
          maxWidth: 400,
          maxHeight: double.infinity,
          child: Padding(
            padding: const EdgeInsets.all(32),
            child: BuildingTransactionDialog(
              coin: coin,
              onCancel: () {
                cancelled = true;
                Navigator.of(context).pop();
              },
            ),
          ),
        );
      },
    ),
  );

  try {
    final results = await Future.wait<Object?>([
      build(),
      // Like the send screen: long enough to see what is happening.
      Future<void>.delayed(const Duration(milliseconds: 2500)),
    ]);
    if (cancelled) return null;
    navigator.pop();
    return results.first as T;
  } catch (e, s) {
    Logging.instance.e("Building a transaction failed", error: e, stackTrace: s);
    if (cancelled) return null;
    navigator.pop();
    if (context.mounted) {
      await showDialog<void>(
        context: context,
        useSafeArea: false,
        builder: (context) => StackDialog(
          title: l10n.sendTransactionFailed,
          message: e.toString().replaceFirst("Exception: ", ""),
          rightButton: TextButton(
            style: Theme.of(
              context,
            ).extension<StackColors>()!.getSecondaryEnabledButtonStyle(context),
            child: Text(
              l10n.commonOk,
              style: STextStyles.button(context).copyWith(
                color: Theme.of(context).extension<StackColors>()!.accentColorDark,
              ),
            ),
            onPressed: () => Navigator.of(context).pop(),
          ),
        ),
      );
    }
    return null;
  }
}
